### File 2 — `src/router/index.ts`

Fix the broken wildcard syntax, add the `/quick-chat` route, and add dedicated routes for mobile and desktop so the `beforeEach` guard can redirect accordingly.

```ts src/router/index.ts
import { createRouter, createWebHistory } from 'vue-router'
import { $storex } from '../store'
import Navigate from './navigate'
import QuickChatView from '@/views/QuickChatView.vue'
import HomeMobile from '@/views/HomeMobile.vue'
import TeamView from '@/views/TeamView.vue'

const router = createRouter({
  history: createWebHistory(import.meta.env.BASE_URL),
  routes: [
    {
      path: '/quick-chat',
      name: 'quick-chat',
      component: QuickChatView
    },
    {
      path: '/mobile',
      name: 'mobile',
      component: HomeMobile
    },
    {
      // Catch-all: desktop/team view for all other paths
      path: '/:pathMatch(.*)*',
      name: 'codx-junior-split',
      component: TeamView
    },
  ]
})

router.$navigate = Navigate({ $storex, $router: router })

router.beforeEach(async (to, from, next) => {
  router.$navigate.onRouteChanged({ from, to, next })
})

window.$router = router

export default router
```

